def sequential_search(arr, element):
    """
    Returns a tuple: (found, index)
      - found: True if element is in arr, else False
      - index: position of the first occurrence of element, or -1 if not found
    """
    for i, val in enumerate(arr):
        if val == element:
            return (True, i)
    return (False, -1)


# Example usage and assertion from your prompt
if __name__ == "__main__":
    assert sequential_search([11,23,58,31,56,77,43,12,65,19], 31) == (True, 3)

